command:example.dev:code:
$patch = Invoke-BGInfoDataSource -Name 'Patch level' -TimeoutSeconds 10 -Default 'unknown' -ScriptBlock {
    (Get-HotFix | Sort-Object InstalledOn -Descending | Select-Object -First 1).HotFixID
}
$tickets = Invoke-BGInfoDataSource -Name 'Open tickets' -Default 0 -ArgumentList $uri -ScriptBlock {
    param($uri) (Invoke-RestMethod -Uri $uri -TimeoutSec 5).count
}

New-BGInfo -Target File {
    New-BGInfoBackground -Width 1920 -Height 1080 -Gradient '#0B1022', '#05070F' -Glow @(
        New-BGInfoBackgroundGlow -X 0.15 -Y 0.1 -Radius 0.55 -Color '#4F46E566'
    ) -Pattern Dots
    New-BGInfoValue -Name 'Host' -Value $env:COMPUTERNAME
} -ConfigurationDirectory $PSScriptRoot -OutputFileName 'Generated.png'

New-BGInfo -Theme Graphite -Target File {
    New-BGInfoLayout -Margin 48 -ColumnWidth 480 -IconAreaWidth 120
    New-BGInfoChart -Region Right -Title 'CPU' -Kind Area -Values 12, 30, 22
    New-BGInfoChart -Region Right -Title 'Memory' -Kind Gauge -Values 64
} -ConfigurationDirectory $PSScriptRoot -OutputFileName 'regions.png'

New-BGInfoList -Region Left -Title 'Before you leave' -Item @(
    @{ Text = 'Save to OneDrive'; Checked = $true }
    @{ Text = 'Sign out'; Checked = $false }
)

$theme = New-BGInfoTheme -Preset Aurora -Mode Light -Accent '#0EA5E9' -Scale 1.33
New-BGInfo -Theme $theme -Target File {
    New-BGInfoBackground -Width 2560 -Height 1440
    New-BGInfoValue -Name 'Host' -Value $env:COMPUTERNAME
    New-BGInfoChart -Region Bottom -Title 'CPU' -Kind Area -Values 12, 30, 22
} -ConfigurationDirectory $PSScriptRoot -OutputFileName 'themed.png'

$tiles = @(
    New-BGInfoVisualCanvasTile -Side Left -IconKind Computer -SurfaceStyle Raised -Label HOSTNAME -Value '{{HostName}}'
    New-BGInfoVisualCanvasTile -Side Right -IconKind Cpu -SurfaceStyle Raised -Label 'CPU LOAD' -Value '31% active' -MiniChartKind Area -MiniChartValues 22,28,25,36,31 -MiniChartMaximum 100
)

New-BGInfo -Target File {
    New-BGInfoVisualCanvas -Title 'PowerBGInfo' -Subtitle 'High-contrast information boxes' -ThemeMode Light -TitleColor White -SubtitleColor White -Tile $tiles
} -FilePath .\Examples\Samples\TapC-Evotec-2560x1080.jpg -ConfigurationDirectory .\Examples\Output -OutputFileName 'PowerBGInfo.VisualCanvas.ContrastBox.jpg' -WallpaperFit Fill
